package fun.hymnmusic.app;
import android.graphics.*;
import android.widget.ImageView;
import java.io.*;
import java.net.*;
final class NativeArtwork {
 static final android.util.LruCache<String,Bitmap> cache=new android.util.LruCache<String,Bitmap>(8*1024*1024){protected int sizeOf(String key,Bitmap value){return value.getByteCount();}};
 static ImageView view(MusicActivity a,String path,int size){ImageView image=new ImageView(a);image.setContentDescription("Cover artwork");image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(a.shape(a.palette.surface,12));image.setClipToOutline(true);image.setMinimumHeight(a.dp(size));Bitmap saved=cache.get(path);if(saved!=null){image.setImageBitmap(saved);return image;}if(path==null||path.isEmpty())return image;int current=a.epoch;a.workers.execute(()->{try{String url=path.startsWith("/")?CustomerApi.BASE+path:path;URL parsed=new URL(url);if(!parsed.getProtocol().equals("https"))return;HttpURLConnection connection=MusicNavigation.internal(url)?a.api.connection(url,"GET"):(HttpURLConnection)parsed.openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(15000);connection.setInstanceFollowRedirects(false);try{if(connection.getResponseCode()!=200)return;ByteArrayOutputStream data=new ByteArrayOutputStream();try(InputStream in=connection.getInputStream()){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1){if(data.size()+n>20*1024*1024)return;data.write(bytes,0,n);}}byte[] bytes=data.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<1||options.outHeight<1)return;options.inSampleSize=Math.max(1,Math.max(options.outWidth,options.outHeight)/600);options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)return;cache.put(path,bitmap);a.runOnUiThread(()->{if(a.epoch==current&&!a.isFinishing())image.setImageBitmap(bitmap);});}finally{connection.disconnect();}}catch(Exception ignored){}});return image;}
}
